import json
from openai import OpenAI

client = OpenAI()
MODEL = "gpt-4.1-mini"  # any tool-calling model

def tool(name, desc, arg):
    return {"type": "function", "function": {"name": name, "description": desc,
            "parameters": {"type": "object", "properties": {arg: {"type": "string"}}, "required": [arg]}}}

TOOLS = [tool("search_docs", "Hybrid search over internal docs; returns chunks with doc ids.", "query"),
         tool("run_sql", "Read-only SQL over the customers database.", "sql")]
IMPL = {"search_docs": hybrid_search, "run_sql": readonly_sql}

def agentic_rag(question: str, max_steps: int = 6) -> str:
    msgs = [{"role": "system", "content": "Search until every claim has evidence; cite doc ids. "
             "If the evidence does not exist, say so."},
            {"role": "user", "content": question}]
    for _ in range(max_steps):  # hard cap bounds latency and cost
        msg = client.chat.completions.create(model=MODEL, messages=msgs, tools=TOOLS).choices[0].message
        if not msg.tool_calls:
            return msg.content  # the model decided the evidence is enough
        msgs.append(msg)
        for call in msg.tool_calls:
            result = IMPL[call.function.name](**json.loads(call.function.arguments))
            msgs.append({"role": "tool", "tool_call_id": call.id, "content": json.dumps(result)})
    return "I couldn't find enough evidence within the step budget."  # abstain, don't guess
